const puml = `@startuml
title <size:24>System Context View: Library</size>

set separator none
left to right direction

<style>
  root {
    BackgroundColor: #ffffff
    FontColor: #444444
  }
</style>

!include <C4/C4>
!include <C4/C4_Context>

Person(Patron, "Patron", $descr="Borrows books at the library.", $tags="", $link="")
System(Library, "Library", $descr="Manages books and loans.", $tags="", $link="")

Rel(Patron, Library, "Browses the catalogue through", $techn="HTTPS", $tags="", $link="")

SHOW_LEGEND(true)
hide stereotypes
@enduml`;
try {
  const res = await fetch("https://www.plantuml.com/plantuml/png", {
    method: "POST",
    headers: { "Content-Type": "text/plain" },
    body: puml,
  });
  const status = res.status;
  const ct = res.headers.get("content-type");
  const buf = new Uint8Array(await res.arrayBuffer());
  const magic = Array.from(buf.slice(0, 8)).map(b => b.toString(16).padStart(2, "0")).join(" ");
  // base64-encode
  let bin = "";
  for (let i = 0; i < buf.length; i += 0x8000) bin += String.fromCharCode(...buf.subarray(i, i + 0x8000));
  const b64 = btoa(bin);
  return { status, ct, size: buf.length, magic, b64 };
} catch (e) {
  return { error: String(e) };
}

